import{_ as t,C as r,c as i,o as s,ag as e,j as n,G as l}from"./chunks/framework.Bw-5EFTY.js";const b=JSON.parse('{"title":"Affiliate Dashboard Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/affiliate-portal/affiliate-dashboard-overview.md","filePath":"guide/affiliate-portal/affiliate-dashboard-overview.md","lastUpdated":1752211575000}'),u={name:"guide/affiliate-portal/affiliate-dashboard-overview.md"};function h(d,a,f,c,p,g){const o=r("ZoomableImage");return s(),i("div",null,[a[0]||(a[0]=e('<h1 id="affiliate-dashboard-overview" tabindex="-1">Affiliate Dashboard Overview <a class="header-anchor" href="#affiliate-dashboard-overview" aria-label="Permalink to &quot;Affiliate Dashboard Overview&quot;">​</a></h1><p>Welcome to your personal affiliate dashboard! This is your central hub for tracking your performance, generating promotional links, and viewing your earnings. Think of it as your command center for all your affiliate activities.</p><p>When you log in to the <strong>Affiliate Portal</strong>, you&#39;ll land on this main dashboard page. At the top, you have your main navigation tabs: <strong>Dashboard</strong>, <strong>Links</strong>, <strong>Referrals</strong>, <strong>Payouts</strong>, <strong>Visits</strong>, and <strong>Settings</strong>, which take you to the different parts of your portal.</p><p>This guide will walk you through all the features and sections available in your dashboard.</p><h2 id="accessing-the-dashboard" tabindex="-1">Accessing the Dashboard <a class="header-anchor" href="#accessing-the-dashboard" aria-label="Permalink to &quot;Accessing the Dashboard&quot;">​</a></h2><p>To access your Affiliate Dashboard:</p><ol><li>Log in to your WordPress site</li><li>Navigate to the Affiliate Portal</li><li>You&#39;ll be taken to your dashboard automatically</li></ol><h3 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h3><p>This section at the top of your dashboard displays four key metrics to give you an instant snapshot of your performance:</p><ul><li><strong>Total Paid:</strong> The total amount of commissions you have already been paid.</li><li><strong>Total Unpaid:</strong> Approved commissions that you have earned but have not yet been paid out.</li><li><strong>Total Referrals:</strong> The total number of successful sales you have generated.</li><li><strong>Conversion Rate:</strong> The percentage of clicks on your links that have turned into successful sales.</li></ul>',10)),n("p",null,[l(o,{src:"/guide/public/images/affiliate-portal/dashboard/affiliate-dashboard-overview.webp",alt:"Affiliate Dashboard Overview"})]),a[1]||(a[1]=e('<h3 id="your-affiliate-link" tabindex="-1">Your Affiliate Link <a class="header-anchor" href="#your-affiliate-link" aria-label="Permalink to &quot;Your Affiliate Link&quot;">​</a></h3><p>This section is front and center, making it easy to grab your primary affiliate link at any time.</p><ul><li><p>Simply click the <strong>Copy</strong> button to copy your unique referral URL to your clipboard.</p></li><li><p>Share this link with your audience to start earning commissions.</p></li><li><p>Click the <strong>Generate Link</strong> button if you want to create a link for a specific page on the site.</p></li></ul><h3 id="_2-recent-referrals" tabindex="-1">2. Recent Referrals <a class="header-anchor" href="#_2-recent-referrals" aria-label="Permalink to &quot;2. Recent Referrals&quot;">​</a></h3><p>At the bottom of the page, you’ll see a list of your most recent successful referrals. This table shows the commission Amount, the payment Status (e.g., Paid), the Date of the sale, and a Description of the item purchased. You can click <strong>View All</strong> to go to the main &quot;<strong>Referrals</strong>&quot; tab for a complete history.</p><h3 id="_3-tips-for-using-your-dashboard" tabindex="-1">3. Tips for Using Your Dashboard <a class="header-anchor" href="#_3-tips-for-using-your-dashboard" aria-label="Permalink to &quot;3. Tips for Using Your Dashboard&quot;">​</a></h3><ul><li><p><strong>Check Daily:</strong> Monitor your performance metrics daily to see what’s working and track your progress.</p></li><li><p><strong>Generate Custom Links:</strong> Use the &quot;Links&quot; tab to create links for specific products or blog posts you want to promote.</p></li><li><p><strong>Track Payments:</strong> Keep an eye on your &quot;Payouts&quot; tab to see your payment history.</p></li><li><p><strong>Update Your Info:</strong> Make sure your payment email in the &quot;Settings&quot; tab is always up to date to ensure you get paid on time.</p></li></ul>',7))])}const m=t(u,[["render",h]]);export{b as __pageData,m as default};
